"""Recommendation engine for AHMS."""

from dataclasses import dataclass
from decimal import Decimal
from typing import List
from .portfolio import Portfolio
from .evaluator import HealthScoreResult, AssetHealthStatus


DISCLAIMER = (
    "Disclaimer: Recommendations are provided for decision-support and portfolio health tracking "
    "purposes only and do not constitute certified financial or investment advice."
)


@dataclass
class Alert:
    """An alert/recommendation generated by the engine."""

    severity: str
    title: str
    message: str
    recommendation: str
    disclaimer: str = DISCLAIMER


class RecommendationEngine:
    """Evaluates portfolio metrics and outputs decision-support alerts."""

    @classmethod
    def generate_recommendations(
        cls,
        portfolio: Portfolio,
        health_result: HealthScoreResult,
    ) -> List[Alert]:
        alerts: List[Alert] = []

        if health_result.diversification_score < Decimal("60.0"):
            alerts.append(
                Alert(
                    severity="high" if health_result.diversification_score < Decimal("40.0") else "medium",
                    title="Concentrated Portfolio Allocation",
                    message=f"Portfolio diversification score is {health_result.diversification_score}/100 with an HHI of {health_result.hhi}.",
                    recommendation="Review asset class allocations and explore spreading capital across uncorrelated asset categories.",
                )
            )

        if health_result.largest_holding_share > Decimal("0.25"):
            pct = (health_result.largest_holding_share * Decimal("100")).quantize(Decimal("0.1"))
            alerts.append(
                Alert(
                    severity="high" if health_result.largest_holding_share > Decimal("0.40") else "medium",
                    title="High Single-Holding Concentration",
                    message=f"The largest single holding represents {pct}% of your total portfolio value.",
                    recommendation="Review concentration risks to avoid over-reliance on a single asset's performance.",
                )
            )

        if health_result.liquidity_score < Decimal("50.0"):
            pct = (health_result.liquid_share * Decimal("100")).quantize(Decimal("0.1"))
            alerts.append(
                Alert(
                    severity="medium",
                    title="Low Liquid Reserve Share",
                    message=f"Liquid assets account for {pct}% of the portfolio, which is below the 50% target.",
                    recommendation="Review emergency fund availability and short-term cash flow requirements.",
                )
            )

        if health_result.income_score < Decimal("40.0"):
            alerts.append(
                Alert(
                    severity="low",
                    title="Low Portfolio Cash Flow",
                    message=f"Trailing 12-month income yield score is {health_result.income_score}/100.",
                    recommendation="Review income-generating holdings (dividends, rental yield, or fixed coupon instruments) if regular cash flow is desired.",
                )
            )

        for asset in portfolio.assets:
            status = AssetHealthStatus.evaluate(asset, portfolio.total_value())
            if status == AssetHealthStatus.WEAK:
                alerts.append(
                    Alert(
                        severity="high",
                        title=f"Asset Health Warning: {asset.name}",
                        message=f"{asset.name} is classified as Weak due to sustained negative returns or a >20% decline from its peak valuation.",
                        recommendation=f"Review performance fundamentals and long-term viability for {asset.name}.",
                    )
                )
            elif status == AssetHealthStatus.WATCH:
                alerts.append(
                    Alert(
                        severity="medium",
                        title=f"Asset on Watchlist: {asset.name}",
                        message=f"{asset.name} requires attention due to outdated valuation or high portfolio weight.",
                        recommendation=f"Review and update recent valuation records for {asset.name}.",
                    )
                )

        return alerts
